-- Configure Transparent Data Encryption (SQL Server)
-- 1. Create master key
USE master;
CREATE MASTER KEY ENCRYPTION BY PASSWORD = 'Complex_P@ssw0rd_2024!';

-- 2. Create certificate
CREATE CERTIFICATE TDE_Cert
WITH SUBJECT = 'Database_Encryption';

-- 3. Create database encryption key
USE YourDatabase;
CREATE DATABASE ENCRYPTION KEY
WITH ALGORITHM = AES_256
ENCRYPTION BY SERVER CERTIFICATE TDE_Cert;

-- 4. Enable encryption
ALTER DATABASE YourDatabase
SET ENCRYPTION ON;

-- 5. Verify status
SELECT 
    db_name(database_id) AS database_name,
    encryption_state,
    percent_complete,
    encryption_state_desc
FROM sys.dm_database_encryption_keys;

-- PostgreSQL: Use advanced indexing for JSON
CREATE TABLE products (
    id SERIAL PRIMARY KEY,
    data JSONB NOT NULL
);

-- GIN index for queries within JSON
CREATE INDEX idx_product_data ON products USING GIN (data);

-- Efficient query in nested JSON
SELECT id, data->'name' AS product_name
FROM products
WHERE data @> '{"category": "electronics", "stock": {"available": true}}';

-- MySQL equivalent (less efficient)
CREATE TABLE products (
    id INT AUTO_INCREMENT PRIMARY KEY,
    data JSON NOT NULL
);

-- MySQL does not support indexes on JSON paths as efficiently
SELECT id, JSON_EXTRACT(data, '$.name') AS product_name
FROM products
WHERE JSON_EXTRACT(data, '$.category') = 'electronics'
  AND JSON_EXTRACT(data, '$.stock.available') = true;

-- Bitmap index for data warehouse
CREATE BITMAP INDEX idx_product_category 
ON sales(product_category);

-- Function-based index
CREATE INDEX idx_upper_email 
ON customers(UPPER(email));

-- Use it in a query
SELECT * FROM customers 
WHERE UPPER(email) = 'contacto@example.invalid';

-- Invisible index for testing
CREATE INDEX idx_test INVISIBLE 
ON orders(customer_id, order_date);

-- Test with session-level setting
ALTER SESSION SET optimizer_use_invisible_indexes = TRUE;
-- Run test queries
ALTER SESSION SET optimizer_use_invisible_indexes = FALSE;

-- If beneficial, make visible
ALTER INDEX idx_test VISIBLE;

-- Generate AWR report manually
@$ORACLE_HOME/rdbms/admin/awrrpt.sql

-- Via SQL: last 24 hours
SELECT output FROM TABLE(
  DBMS_WORKLOAD_REPOSITORY.AWR_REPORT_HTML(
    l_dbid     => (SELECT dbid FROM v$database),
    l_inst_num => 1,
    l_bid      => (SELECT MIN(snap_id) FROM dba_hist_snapshot 
                   WHERE begin_interval_time >= SYSDATE - 1),
    l_eid      => (SELECT MAX(snap_id) FROM dba_hist_snapshot)
  )
);

-- Run SQL Tuning Advisor
DECLARE
  l_task_name VARCHAR2(30);
BEGIN
  l_task_name := DBMS_SQLTUNE.CREATE_TUNING_TASK(
    sql_id      => 'abc123xyz',
    scope       => 'COMPREHENSIVE',
    time_limit  => 3600,
    task_name   => 'tune_slow_query',
    description => 'Tune problematic customer query'
  );

  DBMS_SQLTUNE.EXECUTE_TUNING_TASK(l_task_name);
END;
/

-- See recommendations
SELECT DBMS_SQLTUNE.REPORT_TUNING_TASK('tune_slow_query') 
FROM dual;
